await fs.mkdir(OUT,{recursive:true});const browser=await chromium.launch({headless:true});const report={};for(const [name,viewport,mobile] of [['desktop',{width:1440,height:1000},false],['mobile',{width:390,height:844},true]]){const ctx=await browser.newContext({viewport});const p=await ctx.newPage();try{report[name]=await inspect(p,mobile);await p.screenshot({path:`${OUT}/${name}.png`,fullPage:true})}catch(e){report[name]={errors:[String(e)]}}await ctx.close()}await browser.close();report.pass=!report.desktop.errors.length&&!report.mobile.errors.length;await fs.writeFile(`${OUT}/report.json`,JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));if(!report.pass)process.exitCode=1;
